import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { createSupabaseBrowserClient, isLiveSupabase } from '@/lib/supabase/client';

export interface UserSession {
  id: string;
  email: string;
}

export function useAuth() {
  const [user, setUser] = useState<UserSession | null>(null);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    const supabase = createSupabaseBrowserClient();

    if (isLiveSupabase()) {
      supabase.auth.getSession().then(({ data: { session } }) => {
        if (session?.user) {
          setUser({
            id: session.user.id,
            email: session.user.email || '',
          });
        } else {
          setUser(null);
        }
        setLoading(false);
      });

      const { data: { subscription } } = supabase.auth.onAuthStateChange(
        (_event, session) => {
          if (session?.user) {
            setUser({
              id: session.user.id,
              email: session.user.email || '',
            });
          } else {
            setUser(null);
          }
          setLoading(false);
        }
      );

      return () => {
        subscription.unsubscribe();
      };
    } else {
      // Local dev/demo mode: check local storage
      const stored = localStorage.getItem('pingwatch_user');
      if (stored) {
        try {
          setUser(JSON.parse(stored));
        } catch {
          setUser(null);
        }
      } else {
        // Set default demo user for frictionless local evaluation if desired
        const demoUser = { id: 'usr_demo_123', email: 'demo@pingwatch.test' };
        localStorage.setItem('pingwatch_user', JSON.stringify(demoUser));
        localStorage.setItem('pingwatch_demo_token', 'demo-bearer-token');
        setUser(demoUser);
      }
      setLoading(false);
    }
  }, []);

  const signOut = async () => {
    if (isLiveSupabase()) {
      const supabase = createSupabaseBrowserClient();
      await supabase.auth.signOut();
    }
    localStorage.removeItem('pingwatch_user');
    localStorage.removeItem('pingwatch_demo_token');
    setUser(null);
    router.push('/auth/login');
  };

  return {
    user,
    loading,
    signOut,
    isAuthenticated: !!user,
  };
}
